{SubModule=Arrays Using List, Question=Max Consecutive Ones, TestCaseName(run_code_key)=maxones_valid, Code=def findMaxConsecutiveOnes(nums):
    max_count = 0  # To store the maximum consecutive 1s
    count = 0      # To count the current consecutive 1s

    for num in nums:
        if num == 1:
            count += 1
            if count > max_count:
                max_count = count
        else:
            count = 0  # Reset count when 0 is encountered

    return max_count

